"""Single run.

Usage: python main.py --output <folder>
    [--channel chrome|chromium] [--headless] [--console]

The previous option names (--saida) are still accepted.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from nekkora_rpa import Engine, EnvSecretProvider, SingleInputProvider, TransactionItem, load_config
from nekkora_rpa.data import JsonDirectoryResultSink

from automation.process import InternetSecureAreaProcess

HERE = Path(__file__).resolve().parent
EXIT_CODES = {"COMPLETED": 0, "COMPLETED_WITH_FAILURES": 1, "STOPPED": 2, "INIT_FAILED": 3, "CANCELLED": 4}


def main(argv: list[str] | None = None) -> int:
    """Reads the arguments, runs the process and prints the summary (no values); returns the exit code."""
    parser = argparse.ArgumentParser(description="Generated process: area_segura_the_internet")
    parser.add_argument(
        "--output", "--saida", dest="output", required=True, type=Path, help="run folder (results, events, checkpoint)"
    )
    parser.add_argument("--channel", choices=["chromium", "chrome"])
    parser.add_argument("--headless", action="store_true")
    parser.add_argument("--console", action="store_true")
    args = parser.parse_args(argv)
    run_folder = args.output.resolve()
    run_folder.mkdir(parents=True, exist_ok=True)
    overrides: dict[str, object] = {}
    if args.channel:
        overrides["browser.channel"] = args.channel
    if args.headless:
        overrides["browser.headless"] = True
    config = load_config(HERE / "config" / "execution.toml", overrides)
    process = InternetSecureAreaProcess()
    item = TransactionItem("execucao-unica", {})
    engine = Engine(
        process,
        SingleInputProvider(item),
        JsonDirectoryResultSink(run_folder / "resultados"),
        config,
        secrets=EnvSecretProvider(process.required_secrets),
        run_dir=run_folder / "execucao",
        console=args.console,
    )
    summary = engine.run()
    fields = summary.to_dict()
    published = ("execution_id", "status", "stop_code", "stop_detail", "counts")
    print(json.dumps({key: fields[key] for key in published}))
    return EXIT_CODES[summary.status.value]


if __name__ == "__main__":
    sys.exit(main())
